    m18_b, m18_s = rewrite([(CLLIVE, "**N ≥ 236** → `SESSION_NOTES.md`")], [BANNER, shard])
    m19_b, m19_s = rewrite([(CL238, "**235 ≤ N ≤ 238** → `SESSION_NOTES-S238-through-S236.md`")],
                           [BANNER, shard])
