    m22_b, m22_s = rewrite(swap, [BANNER, shard])
    m23_p, m23_a = rewrite(swap, [POINTER, after])

    # M24/M25/M38/M39/M47 rewrite ROUTING as well, so even the declaration is self-consistent.
    short = [(CL238, "**236 ≤ N ≤ 237** → `SESSION_NOTES-S238-through-S236.md`"),
