        return s

    def prose_with(old, new):
        assert any(old in l for _w, l, _f, _k in SIZE_PROSE), "fixture missing in SIZE_PROSE: %r" % old
        return tuple((w, l.replace(old, new, 1), f, k) for w, l, f, k in SIZE_PROSE)

    m60 = sizes_with(archived_headings=4)
    m61 = sizes_with(archived_lines=593)
    m62 = sizes_with(shard_total=653)
    # M63 mis-states the cap CONSISTENTLY — declaration, banner and declared literal together — so
