    m64_a = after.replace("3 record headings, 583 lines", "3 record headings, 593 lines", 1)
    m64_pr = prose_with("3 record headings, 583 lines", "3 record headings, 593 lines")
    m65 = reach_with(BACKLOG, "`SESSION_NOTES-S238-through-S236.md` (644 lines)",
                     "`SESSION_NOTES-S238-through-S236.md` (463 lines)")
    m66 = reach_with(README, "newest 4 sessions", "newest 5 sessions")
    m67_b = BANNER.replace("— three record", "— four record", 1)
    m67_s = shard.replace("— three record", "— four record", 1)
    m67_pr = prose_with("— three record", "— four record")
    m68 = sizes_with(retained_records=5)

    # --- NEW at this trim: L13's six arms and L12's new one. Fifteen mutants, M69-M83. --------
    # M69 moves the DECLARED filename and leaves every artifact alone, which is how a renamed
    # shard is simulated without creating one — the same shape M60-M62 use for sizes. M70, M71,
    # M73 and M75 move a span (or the census word) in the prose TOGETHER with every declaration
    # that pins that prose by equality, so L2/b1 and L6 are satisfied and L13 is the only
    # assertion left able to object.
    #
    # M72, M74 and M76 move a span in one of the three out-of-reach files and leave SPAN_PROSE's
    # literal correct, so what fires is the DIVERGENCE arm (`literal not in text`), never the span
    # arm. That is worth stating plainly because the first draft of this comment claimed otherwise
    # and an adversarial review measured it: with the span arm neutered, M72/M74/M76 are still
    # caught. SPAN_PROSE's literal IS an equality-pinned declaration for those sentences. M78, M79
    # and M80 below move the literal too, which is what actually exercises L13/span outside the
    # pointer and the banner — 2 of 8 declared sentences before they existed.
    def span_with(old, new):
        assert any(old in l for _w, l, _s, _k in SPAN_PROSE), "fixture missing in SPAN_PROSE: %r" % old
        return tuple((w, l.replace(old, new, 1), s, k) for w, l, s, k in SPAN_PROSE)

    m69_base = "SESSION_NOTES-S238-through-S235.md"
    m70_p = POINTER.replace("Archived Sessions 238 → 236 —", "Archived Sessions 238 → 235 —", 1)
    m70_a = after.replace("Archived Sessions 238 → 236 —", "Archived Sessions 238 → 235 —", 1)
    m70_sp = span_with("Archived Sessions 238 → 236 —", "Archived Sessions 238 → 235 —")
    m71_b = BANNER.replace("archive shard: Sessions 238 → 236",
                           "archive shard: Sessions 238 → 237", 1)
    m71_s = shard.replace("archive shard: Sessions 238 → 236",
                          "archive shard: Sessions 238 → 237", 1)
    m71_sp = span_with("archive shard: Sessions 238 → 236", "archive shard: Sessions 238 → 237")
    m72 = reach_with(README, "Sessions 238->236 (grep it; do not Read it)",
                     "Sessions 238->235 (grep it; do not Read it)")
    m73_p = POINTER.replace("holds Sessions 242 → 239 only", "holds Sessions 242 → 240 only", 1)
    m73_a = after.replace("holds Sessions 242 → 239 only", "holds Sessions 242 → 240 only", 1)
    m73_sp = span_with("holds Sessions 242 → 239 only", "holds Sessions 242 → 240 only")
    m74 = reach_with(CONVENTIONS, "(Session 242, Sessions 238→236)",
                     "(Session 242, Sessions 238→237)")
    # The word this mutant moves MUST be the one WORDS renders for len(SPAN_PROSE); when the census
    # sentence was reworded mid-session this mutant silently became a no-op and SURVIVED, which is
    # how it was found. A mutant that passes is a bug in the mutant until proven otherwise.
    assert "eight" in SPAN_CENSUS, "M75 fixture broken: the census word is not the one WORDS renders"
    m75_cen = SPAN_CENSUS.replace("eight", "nine", 1)
