    m75_p = POINTER.replace(SPAN_CENSUS, m75_cen, 1)
    m75_a = after.replace(SPAN_CENSUS, m75_cen, 1)
    m76 = reach_with(CLAUDE, "`SESSION_NOTES-S238-through-S236.md` (238→236",
                     "`SESSION_NOTES-S238-through-S236.md` (238→237")

