    m78 = reach_with(README, "Sessions 238->236 (grep it", "Sessions 238->235 (grep it")
    m78_sp = span_with("Sessions 238->236 (grep it", "Sessions 238->235 (grep it")
    m79 = reach_with(CONVENTIONS, "(Session 242, Sessions 238→236)", "(Session 242, Sessions 238→237)")
