        ("M3  one character flipped inside an archived record", before, after,
         sub_in_shard(sr[1], sr[1].replace("e", "3", 1)), claude, None, SAME, reach, lineage, provenance),
        ("M4  one character flipped inside a retained record", before,
         after.replace(ar[-1], ar[-1].replace("e", "3", 1), 1), shard, claude, None, SAME, reach, lineage, provenance),
        ("M5  two adjacent archived records swapped", before, after,
         sub_in_shard(sr[1] + sr[2], sr[2] + sr[1]), claude, None, SAME, reach, lineage, provenance),
        ("M6  a front-matter line MOVED from the live file into the shard banner", before,
         after.replace(purpose + "\n", "", 1),
         shard.replace("---\n\n### What Session", purpose + "\n\n---\n\n### What Session", 1),
         claude, None, SAME, reach, lineage, provenance),
        ("M7  a trailing file-scoped block appended below the shard's last record", before, after,
         shard + "\n---\n\ntrailing paragraph\n", claude, None, SAME, reach, lineage, provenance),
        ("M8  the pointer block dropped from the live front matter", before,
         after.replace(POINTER, "", 1), shard, claude, None, SAME, reach, lineage, provenance),
        ("M9  U+2212 silently normalised to ASCII '-' in an archived record", before, after,
         sub_in_shard("−", "-"), claude, None, SAME, reach, lineage, provenance),
        ("M10 declared substitution 1 not applied (stale 'holds Sessions 239 → 236 only')", before,
         after.replace(FRONT_SUBST[0][1], FRONT_SUBST[0][0], 1), shard, claude, None, SAME, reach, lineage, provenance),
